UIPuffSprite=function(game){var randomPuffIndex=Math.floor(Math.random()*3);Phaser.Sprite.call(this,game,0,0,'game','puff'+randomPuffIndex);this.scale.setTo(UIConstants.GAME_ASSET_SCALE,UIConstants.GAME_ASSET_SCALE);this.kill();}
UIPuffSprite.prototype=Object.create(Phaser.Sprite.prototype);UIPuffSprite.prototype.constructor=UIPuffSprite;UIPuffSprite.prototype.spawn=function(x,y,speedX,speedY){this.reset(x,y);this.game.physics.p2.enable(this);this.body.allowSleep=false;this.body.dynamic=true;this.body.fixedRotation=true;this.body.damping=0.1;this.alpha=0.2+Math.random()*(0.3-0.2);this.scale.set((0.5+Math.random())*UIConstants.GAME_ASSET_SCALE);this.body.setRectangle(this.width,this.height);this.body.setMaterial(UIUtils.puffMaterial);this.body.setCollisionGroup(UIUtils.puffCollisionGroup);this.body.collides(UIUtils.wallCollisionGroup);this.body.velocity.x=speedX+Math.random()*250.0-125.0;this.body.velocity.y=speedY+Math.random()*250.0-125.0;}
UIPuffSprite.prototype.update=function(){if(!this.exists){return;}if(this.game.physics.arcade.isPaused){return;}Phaser.Sprite.prototype.update.call(this);this.alpha=Math.max(0.0,this.alpha-(0.03-Math.random()*0.0083));this.scale.set(this.scale.x+0.0415,this.scale.y+0.0415);if(this.alpha==0.0){this.kill();}}
UIPuffSprite.prototype.retire=function(){this.kill();}